import{_ as t,o as a,c as _,a4 as r}from"./chunks/framework.C3unmAF4.js";const i=JSON.parse('{"title":"北京海淀：“小农业”承载“大科技”走出强农新路","description":"","frontmatter":{"sidebar":false,"aside":false,"editLink":false,"lastUpdated":false,"prev":false,"next":false,"title":"北京海淀：“小农业”承载“大科技”走出强农新路","date":"2026-08-20T00:00:00.000Z","source":"农业农村部智慧农业专题","category":"news","link":"https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202608/t20260807_6486512.htm","summary":"地处北京国际科技创新中心核心区的海淀区,耕地仅有2.18万亩,永久基本农田1.1万亩,农业用地资源十分有限。依托区域雄厚科研家底,海淀区正走出一条科技强农特色路径。数据显示,2023年海淀区乡村全面振兴发展指数位居北京13个涉农区首位;2025年全区农业发明专利申请占全市超40%,农林牧渔业总产值同比增长9.7%,粮食总产量较“十三五”末实现翻番。...\\n","contentHash":"9cd2ad85b1d77d9ff9bb0b0778587afe","tags":["智慧农业","行业资讯"]},"headers":[],"relativePath":"news/2026-08-20-北京海淀-小农业-承载-大科技-走出强农新路.md","filePath":"news/2026-08-20-北京海淀-小农业-承载-大科技-走出强农新路.md"}'),n={name:"news/2026-08-20-北京海淀-小农业-承载-大科技-走出强农新路.md"};function s(o,e,p,l,d,c){return a(),_("div",null,[...e[0]||(e[0]=[r('<h1 id="北京海淀-小农业-承载-大科技-走出强农新路" tabindex="-1">北京海淀：“小农业”承载“大科技”走出强农新路 <a class="header-anchor" href="#北京海淀-小农业-承载-大科技-走出强农新路" aria-label="Permalink to &quot;北京海淀：“小农业”承载“大科技”走出强农新路&quot;">​</a></h1><blockquote><p>来源: <a href="https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202608/t20260807_6486512.htm" target="_blank" rel="noreferrer">农业农村部智慧农业专题</a><br> 日期: 2026-08-20 摘要: 地处北京国际科技创新中心核心区的海淀区,耕地仅有2.18万亩,永久基本农田1.1万亩,农业用地资源十分有限。依托区域雄厚科研家底,海淀区正走出一条科技强农特色路径。数据显示,2023年海淀区乡村全面振兴发展指数位居北京13个涉农区首位;2025年全区农业发明专利申请占全市超40%,农林牧渔业总产值同比增长9.7%,粮食总产量较“十三五”末实现翻番。...</p></blockquote><p>海淀发展智慧农业的核心底气,来自高密度集聚的涉农创新资源。区域汇集中国农科院、中国农大、北京市农林科学院等科研国家队,清华、北航等重点高校协同发力,布局23家农业领域全国重点实验室,集聚56名涉农院士,占全国涉农院士总数过半。目前,全区有188家涉农科技企业,包含25家头部企业、63家腰部企业,产业梯队完整。</p><p>为打通产学研壁垒,海淀区组建农业科技创新联合会,搭建院校、企业协同创新平台;海淀区农业农村局建立“行业管理+街镇属地”联动机制,联动29个街镇统筹服务。2024年海淀区首次设立农业科创专项,加速技术产出转化。</p><p>多年来,海淀农业发明专利申请量长期占北京半数以上,2024年突破60%,拥有4320件高价值涉农发明专利;生物育种领域北京专利全国领先,海淀贡献超八成份额。2025年全国发布15款农业大模型,其中8款出自海淀,区域种业企业种子销售额占全市58%。</p><p>“农业科技创新不是从零起步,而是依托人工智能、生命科学、信息技术优势借势而上。”海淀区农业农村局负责人说,将城市前沿科技嫁接农业,是海淀独有的发展模式。</p><p>实验室成果源源不断落地田间。上庄京西稻智慧农场依靠物联网、北斗无人驾驶设备实现全程自动化,节水节肥超三成,人工成本降低八成。温泉镇建成全国首个生产型蔬菜无人农场,厘米级北斗农机作业效率十倍于人工。翠湖智慧农业创新工场打造京津冀最大单体智能温室,设备国产化率85%,番茄单产位居全国前列。</p><p>多款国产农业机器人达到国际先进水平。海淀区农业农村局与赵春江团队合作研发草莓采摘机器人破损率仅3%,优于海外产品;番茄巡检机器人作业成功率近百分之百,相关设备已推广至全国5省市,创收1870余万元。神农大模型2.0进驻5G草莓温室,可智能监测长势、识别病虫害。</p><p>下一步,海淀区将构建“1+3+X”农业科创体系,围绕智慧农业、智能制造、合成生物三大赛道持续发力,计划“十五五”末培育2至3家领军企业,打造可复制、可推广的“未来农业”海淀模式。</p><p><a href="https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202608/t20260807_6486512.htm" target="_blank" rel="noreferrer">阅读原文</a></p>',10)])])}const h=t(n,[["render",s]]);export{i as __pageData,h as default};
